OBJS = ["base1", "u_green", "inverted_u_brown", "hex_blue", "hex_red", "base2"]

def check(ctx):
    if "ref" not in ctx.state:
        ctx.state["ref"] = {}
    ref = ctx.state["ref"]
    worst = 0.0
    worst_id = ""
    for o in OBJS:
        p = ctx.object_pose(o)
        if p is None:
            continue
        pos = p["pose"]["position"]
        if o not in ref:
            ref[o] = pos
            continue
        d = ctx.dist(pos, ref[o])
        if d > worst:
            worst = d
            worst_id = o
    if worst > ctx.value("disturbance_m"):
        return {"value": worst, "detail": worst_id + " displaced " + str(round(worst, 4)) + " m from its run-start pose"}
    return None

def check(ctx):
    d = ctx.depth()
    if d is None:
        return None
    if "ref" not in ctx.state:
        ctx.state["ref"] = d.copy()
        return None
    diff = np.abs(d - ctx.state["ref"])
    valid = np.isfinite(diff)
    n = int(valid.sum())
    if n == 0:
        return None
    frac = float((diff[valid] > ctx.value("delta_m")).sum()) / n
    if frac > ctx.value("frac"):
        return {"value": frac, "detail": "large depth change across workspace"}
    return None

